import{_ as e,o as a,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"api/introduction.md","filePath":"api/introduction.md","lastUpdated":1789464754000}'),s={name:"api/introduction.md"};function d(n,t,i,h,c,p){return a(),o("div",null,t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Bagisto&#39;s REST and GraphQL APIs come from one Composer package, <code>bagisto/bagisto-api</code>, built on API Platform for Laravel and kept outside the core repository. Each resource is declared once and served over both transports by the same providers and processors, so the data and the business rules match. This page helps you choose a surface (Shop or Admin) and a transport (REST or GraphQL).</p><h2 id="choosing-the-shop-or-admin-api" tabindex="-1">Choosing the Shop or Admin API <a class="header-anchor" href="#choosing-the-shop-or-admin-api" aria-label="Permalink to &quot;Choosing the Shop or Admin API&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Shop API</th><th>Admin API</th></tr></thead><tbody><tr><td>Built for</td><td>Storefronts, mobile shopping apps, headless front ends</td><td>Back-office apps and server-to-server integrations</td></tr><tr><td>REST</td><td><code>/api/shop/*</code></td><td><code>/api/admin/*</code></td></tr><tr><td>GraphQL</td><td><code>POST /api/graphql</code></td><td><code>POST /api/admin/graphql</code></td></tr><tr><td>Credential</td><td>A storefront key, plus a customer or guest-cart token for account, cart and checkout calls</td><td>An Integration token issued for one admin user</td></tr><tr><td>Where it runs</td><td>Anywhere: the storefront key is public by design, and a customer&#39;s token scopes account calls to that customer</td><td>On a server only: the token carries its admin&#39;s permissions</td></tr><tr><td>Playgrounds</td><td>Swagger UI at <code>/api/shop</code>, GraphiQL at <code>/api/graphiql</code></td><td>Swagger UI at <code>/api/admin</code>, GraphiQL at <code>/api/admin/graphiql</code></td></tr></tbody></table><p>The surfaces share neither credentials nor schemas: a Shop operation isn&#39;t reachable on the Admin GraphQL endpoint, and the other way round. The Admin API mirrors what the admin can do, and a token never does more than its admin&#39;s role allows. An AI agent that acts inside the shopper&#39;s browser needs neither surface: the storefront declares its actions as <a href="./../ai/webmcp.html">WebMCP</a> tools, with no package and no token.</p><h2 id="choosing-rest-or-graphql" tabindex="-1">Choosing REST or GraphQL <a class="header-anchor" href="#choosing-rest-or-graphql" aria-label="Permalink to &quot;Choosing REST or GraphQL&quot;">​</a></h2><p>Both transports reach the same resources, so choose by how your client works:</p><table tabindex="0"><thead><tr><th>Pick</th><th>When</th></tr></thead><tbody><tr><td>REST</td><td>Each screen reads or changes one resource at a time; you want HTTP status codes, paging headers and GET requests a cache can store; you upload files such as product images or import files, which only REST accepts</td></tr><tr><td>GraphQL</td><td>A screen needs many related fields in one round trip; you want to select only the fields you render; your front end already uses a GraphQL client</td></tr></tbody></table><p>One client can use both with the same key and tokens, for example GraphQL for catalog pages and REST for an upload.</p><h2 id="packages-for-older-releases" tabindex="-1">Packages for Older Releases <a class="header-anchor" href="#packages-for-older-releases" aria-label="Permalink to &quot;Packages for Older Releases&quot;">​</a></h2><p>Before <code>bagisto/bagisto-api</code>, Bagisto&#39;s APIs were two separate packages. Their last releases are for Bagisto 2.3:</p><table tabindex="0"><thead><tr><th>Package</th><th>Latest release</th><th>Built on</th><th>Requirement in its README</th></tr></thead><tbody><tr><td><code>bagisto/rest-api</code></td><td>v2.3.1</td><td>L5-Swagger and Laravel Sanctum</td><td>Bagisto 2.3.x</td></tr><tr><td><code>bagisto/graphql-api</code></td><td>v2.3.2</td><td>Lighthouse and JWT authentication</td><td>Bagisto 2.3.0</td></tr></tbody></table><p>Their endpoints, install commands and authentication differ from <code>bagisto/bagisto-api</code>, so instructions written for them don&#39;t apply to it.</p><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p><a href="./installation.html">Installation</a> installs the package and issues the credentials each surface needs.</p>',15)]))}const m=e(s,[["render",d]]);export{u as __pageData,m as default};
